  "materia": "filosociologia",
  "topico": "Sociologia clássica",
  "nivel": "Difícil",
  "enunciado": "Max Weber, ao contrário de Marx, enfatiza em sua sociologia:",
  "alternativas": [
   "Apenas a estrutura econômica.",
   "A ação social — a conduta individual dotada de sentido para quem a pratica.",
   "A negação de qualquer método científico.",
   "A luta de classes como único motor da história.",
   "A biologia como base da sociedade."
  ],
  "correta": 1,
  "explicacao": "Weber parte da ação social: o indivíduo age orientando-se pelo comportamento dos outros e atribuindo sentido à ação. É uma abordagem compreensiva, centrada no sujeito, diferente do foco estrutural de Marx.",
  "dica": "Marx pensa em ESTRUTURA/classe; Weber, no INDIVÍDUO e no sentido da ação.",
