  "topico": "Físico-Química",
  "nivel": "Médio",
  "enunciado": "Em um equilíbrio químico, ao se aumentar a concentração de um reagente, pelo princípio de Le Chatelier o equilíbrio:",
  "alternativas": [
   "Desloca-se para formar mais reagente.",
   "Desloca-se no sentido dos produtos, consumindo o excesso.",
   "Permanece inalterado.",
   "Para completamente.",
   "Inverte-se por completo."
  ],
  "correta": 1,
  "explicacao": "O sistema reage para minimizar a perturbação. Aumentando um reagente, o equilíbrio se desloca para o lado dos produtos, consumindo o excesso adicionado.",
  "dica": "O equilíbrio sempre 'foge' da perturbação: adicionou reagente → vai para produtos.",
