  "topico": "Físico-Química",
  "nivel": "Médio",
  "enunciado": "Um processo que LIBERA calor para o ambiente é classificado como:",
  "alternativas": [
   "Endotérmico (ΔH > 0)",
   "Exotérmico (ΔH < 0)",
   "Isotérmico sem troca de calor",
   "Adiabático crescente",
   "Endergônico luminoso"
  ],
  "correta": 1,
  "explicacao": "Reações exotérmicas liberam calor, com variação de entalpia negativa (ΔH < 0), como a combustão. Endotérmicas absorvem calor (ΔH > 0), como a fotossíntese.",
