  "enunciado": "Um mastro de 24 m é preso por um cabo fixado a 7 m de sua base. Qual o comprimento da diagonal/hipotenusa (em metros)?",
  "explicacao": "Teorema de Pitágoras: hip² = 7² + 24² = 49 + 576 = 625. Logo hip = √625 = 25 m.",
